import UIKit

enum CIODebugButtonImage {

    // Embedded rather than bundled because the Swift package (tools 5.1) can't ship resources. 114px PNG = 38pt @3x.
    static let image: UIImage? = Data(base64Encoded: CIODebugButtonImage.base64).flatMap { UIImage(data: $0, scale: 3) }

    private static let base64 = ""
}
